const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const moodNames={secret:'속마음',cheer:'작은 응원',silly:'엉뚱한 생각'};
let farm=null,page='farm',filter='all',busy=false,refreshing=false,selected=null,currentNote=null,plantRequestId=null,generation=0,toastTimer,lastPlotMarkup='';
function plantArt(mood='secret',uprooted=false,growing=false){
 const color={secret:'#d1ad9e',cheer:'#d4ba82',silly:'#c1a7b6'}[mood]||'#d1ad9e';
 return `<svg viewBox="0 0 80 95" xmlns="http://www.w3.org/2000/svg" shape-rendering="crispEdges" aria-hidden="true"><ellipse cx="40" cy="83" rx="28" ry="5" fill="#73864c" opacity=".13"/>${uprooted?`<path d="M28 42h25v6h5v25h-6v7h-8v8h-6V77h-5v9h-6V73h-6V49h7z" fill="${color}"/><path d="M29 46h5v23h-5z" fill="#fff4d1" opacity=".3"/><path d="M24 55h-7v9h-4v5h7v-5h7m28-9h7v9h4v5h-7v-5h-7" fill="${color}"/><path d="M31 55h4v5h-4zm15 0h4v5h-4z" fill="#4f5740"/><path d="M36 65h9v3h-9z" fill="#af7569"/><path d="M27 62h6v3h-6zm22 0h6v3h-6z" fill="#e8a6a0"/>`:`<path d="M13 75h54v4h7v5H7v-5h6z" fill="#b7a17d"/><path d="M13 79h54v3H13z" fill="#c6b18d"/><path d="M20 75h5v3h-5zm32 1h4v3h-4z" fill="#947d5c"/>`}
 <g transform="${growing?'translate(10 26) scale(.75)':''}"><path d="M38 50V26h5v24z" fill="#5f814a"/><path d="M37 35H23v-5h-8V19h14v5h8zm6-5V19h7v-6h15v10h-8v7z" fill="#73975a"/><path d="M37 30H25v-6h-7v-5h11v5h8zm6-5v-6h9v-4h10v4H52v6z" fill="#a1ba73"/><path d="M36 27V13h-5V6h10v7h5v14z" fill="#577e48"/><path d="M36 8h4v17h-4z" fill="#84a761"/>${!uprooted?'<path d="M38 50h5v27h-5z" fill="#6e8b50"/>':''}</g></svg>`;
}
function heroArt(){return `<svg viewBox="0 0 520 335" xmlns="http://www.w3.org/2000/svg" shape-rendering="crispEdges"><path d="M50 254h420v12H50zM32 266h456v18H32zM59 284h405v13H59z" fill="#e0e7cf"/><path d="M79 252h364v8H79zM64 260h390v11H64z" fill="#c8d4b2"/><path d="M51 205h7v51h-7zm38-9h7v60h-7zm43-3h7v63h-7zm-92 27h115v6H40zm0 18h115v6H40z" fill="#bfc6a7"/><path d="M371 192h7v63h-7zm40 3h7v62h-7zm41 8h7v54h-7zm-94 12h114v6H358zm0 20h114v6H358z" fill="#bfc6a7"/><path d="M193 237h151v7h14v15H178v-15h15z" fill="#b59c76"/><path d="M190 245h156v5H190zm12 9h127v4H202z" fill="#cab28b"/><path d="M220 230h5v5h-5zm92 7h6v4h-6z" fill="#826d50"/><g transform="translate(182 67) scale(2.05)">${plantArt('secret',true).replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g transform="translate(337 164) scale(.85)">${plantArt('cheer',true).replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g transform="translate(96 172) scale(.75)">${plantArt('silly',false).replace(/<svg[^>]*>|<\/svg>/g,'')}</g><path d="M145 91h7v123h-7zm-39-14h85v39h-85z" fill="#aa9067"/><path d="M110 81h77v31h-77z" fill="#c5af85"/><path d="M115 87h67v2h-67zm0 16h67v2h-67z" fill="#a88c62"/><text x="148" y="100" text-anchor="middle" font-size="8" fill="#f9f0d6" font-family="monospace">WORDS GROW HERE</text><path d="M355 86h5v5h-5zm5-5h5v5h-5zm-5-5h5v5h-5zm-5 5h5v5h-5z" fill="#c5cc9c"/><path d="M392 133h3v3h-3zm3-3h3v3h-3zm-3-3h3v3h-3zm-3 3h3v3h-3z" fill="#bcc69a"/><path d="M83 149h17v3H83zm9-8h3v19h-3z" fill="#ccd2aa"/><path d="M83 147h18v7H83z" fill="#ede1b5"/><path d="M74 267h3v-10h3v10h3v-5h3v8H74zm334 4h3v-14h3v14h3v-9h3v12h-12z" fill="#9eb785"/><path d="M159 278h5v5h-5zm280-8h4v4h-4z" fill="#bca27d"/><path d="M325 275h12v3h-12zm3-4h6v10h-6z" fill="#fff5ce"/></svg>`}
$('#brandPlant').innerHTML=plantArt('cheer',true);$('#heroIllustration').innerHTML=heroArt();$('#letterPlant').innerHTML=plantArt('cheer',true);
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
async function api(path,data){if(data)generation++;let res;try{res=await fetch('./api'+path,{method:data?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:data?{'Content-Type':'application/json','X-Mandragora':'1'}:{},body:data?JSON.stringify(data):undefined})}catch{throw Error('농장으로 가는 길이 끊겼어요. 잠깐 뒤에 다시 와주세요.')}
 const result=await res.json();if(!res.ok){const e=Error(result.error||'잠깐 뒤 다시 만나요.');e.status=res.status;throw e}return result;}
async function refresh(){if(refreshing||busy||document.hidden)return;refreshing=true;const epoch=generation;try{const next=await api('/farm');if(epoch===generation&&!busy){farm=next;render();$('#connection').textContent='같은 밭에서 함께 자라는 중';$('#connection').classList.remove('offline')}}catch(e){$('#connection').textContent='밭에 연결하지 못했어요 · 새로고침 ↻';$('#connection').classList.add('offline')}finally{refreshing=false}}
function navigate(next){page=['farm','planted','basket'].includes(next)?next:'farm';filter='all';history.replaceState(null,'','#'+page);render()}
function render(){if(!farm)return;$('#plantedCount').textContent=farm.stats.planted;$('#basketCount').textContent=farm.stats.received;$('#waiting').textContent=farm.stats.waiting;$('#harvested').textContent=farm.stats.harvested;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#hero').hidden=page!=='farm';$('#howStrip').hidden=page!=='farm';$('.farm-frame').hidden=page!=='farm';$('#notebook').hidden=page==='farm';$('.field-status').hidden=page!=='farm';$('.field-summary').hidden=page!=='farm';
 const title={farm:['THE COMMUNITY GARDEN','오늘의 만드라고라 밭','마음에 드는 잎사귀를 골라보세요. 어떤 말이 숨어 있을까요?'],planted:['MY LITTLE GARDEN','내가 심어둔 마음들','누군가에게 닿기를 기다리는 말들과, 잘 전해진 마음들.'],basket:['WORDS THAT FOUND ME','나의 수확 바구니','우연히 내게 온 말들. 언제든 다시 꺼내 읽어보세요.']}[page];$('#sectionEyebrow').textContent=title[0];$('#sectionTitle').textContent=title[1];$('#sectionDescription').textContent=title[2];
 document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));
 if(page==='farm')renderPlots();else renderNotes();
}
function renderPlots(){const plots=farm.plots.filter(p=>filter==='all'||p.mood===filter);let html=plots.map((p,i)=>{const waiting=p.readyAt>Date.now(),label=p.mine?'다른 농부를 기다려요':waiting?'뿌리 내리는 중':'누군가의 '+moodNames[p.mood];return `<button class="plot ${p.mine?'mine':''}" data-plot="${p.id}" aria-label="${esc(label)} ${i+1}번 만드라고라"><span class="plot-no">${String(i+1).padStart(2,'0')}</span>${p.mine?'<span class="mine-tag">내 씨앗</span>':''}<span class="plot-art">${plantArt(p.mood,false,waiting)}</span><span class="plot-label">${esc(label)}</span></button>`}).join('');const empty=Math.max(0,12-plots.length);for(let i=0;i<empty;i++)html+=`<button class="plot empty" data-empty aria-label="빈 밭에 말 심기"><span class="plot-no">${String(plots.length+i+1).padStart(2,'0')}</span><span class="empty-art">+</span><span class="plot-label">말이 자랄 자리</span></button>`;if(html===lastPlotMarkup)return;lastPlotMarkup=html;$('#plots').innerHTML=html;document.querySelectorAll('[data-plot]').forEach(b=>b.onclick=()=>selectPlant(b.dataset.plot));document.querySelectorAll('[data-empty]').forEach(b=>b.onclick=openPlant)}
function renderNotes(){const notes=(page==='planted'?farm.planted:farm.basket).filter(n=>(filter==='all'||n.mood===filter)&&(!n.reported||page==='planted'));$('#notebook').innerHTML=`<div class="notes-grid">${notes.length?notes.map(n=>`<${page==='basket'?'button':'article'} class="note-card" ${page==='basket'?'data-note="'+n.id+'"':''}><small><i class="dot ${n.mood}"></i>${moodNames[n.mood]} · ${new Date(n.created).toLocaleDateString('ko-KR')}</small><p>${esc(n.body)}</p><span>${page==='planted'?(n.harvested?(n.thanked?'<b>♡ 마음 잘 받았대요</b>':'누군가에게 전해졌어요'):'아직 밭에서 자라고 있어요'):(n.thanked?'♡ 마음을 전했어요':'나에게 온 익명의 말 · 다시 읽기 ↗')}</span></${page==='basket'?'button':'article'}>`).join(''):`<div class="empty-note"><strong>${page==='planted'?'아직, 비어 있는 작은 밭.':'아직, 가벼운 바구니.'}</strong>${page==='planted'?'말 한 마디를 심어보세요.<br>누군가에겐 오늘 가장 필요한 말일지도 몰라요.':'농장에서 잎사귀 하나를 골라보세요.<br>어떤 마음이 당신을 기다리고 있을까요?'}</div>`}</div>`;document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>showNote(farm.basket.find(n=>n.id===b.dataset.note),false))}
function openPlant(){if(!farm){toast('농장에 연결한 뒤 다시 시도해주세요.');return}if(busy)return;$('#plantError').textContent='';$('#plantDialog').showModal();$('#seedText').focus()}
$('#plantHero').onclick=openPlant;$('#plantSmall').onclick=openPlant;$('#seedText').oninput=()=>{const length=Array.from($('#seedText').value).length;$('#charCount').textContent=length+' / 280';$('#charCount').style.color=length>280?'#ab7057':'';plantRequestId=null};
$('#plantForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const body=$('#seedText').value.trim();if(!body||Array.from(body).length>280){$('#plantError').textContent='1~280자 사이의 말을 심어주세요.';return}if(!plantRequestId)plantRequestId=crypto.randomUUID();busy=true;$('#plantSubmit').disabled=true;$('#plantError').textContent='';try{const next=await api('/plant',{body,mood:$('input[name="mood"]:checked').value,requestId:plantRequestId});farm=next;plantRequestId=null;$('#seedText').value='';$('#charCount').textContent='0 / 280';$('#plantDialog').close();navigate('farm');toast('말 한 마디를 심었어요. 어떤 사람에게 닿을까요?');$('#field').scrollIntoView({behavior:'smooth'})}catch(err){$('#plantError').textContent=err.message}finally{busy=false;$('#plantSubmit').disabled=false}};
function selectPlant(id){if(busy)return;const p=farm.plots.find(p=>p.id===id);if(!p)return;if(p.mine){toast('내가 심은 말은 다른 농부에게 맡겨두어요.');return}if(p.readyAt>Date.now()){toast('뿌리를 내리는 중이에요. '+Math.ceil((p.readyAt-Date.now())/1000)+'초만 기다려주세요.');return}selected=p;currentNote=null;$('#harvestEyebrow').textContent='A WORD IS WAITING FOR YOU';$('#harvestCharacter').innerHTML=plantArt(p.mood,false);$('#harvestCharacter').classList.remove('pulled');$('#harvestTitle').textContent='이 아이를 뽑아볼까요?';$('#harvestIntro').innerHTML='어떤 말인지 아무도 몰라요.<br>당신에게만 들려줄 거예요.';$('#harvestIntro').hidden=false;$('#harvestMessage').hidden=true;$('#harvestSubmit').hidden=false;$('#harvestActions').hidden=true;$('#harvestError').textContent='';$('#harvestFoot').textContent='한 만드라고라는 한 사람에게만 전해져요.';$('#harvestDialog').showModal()}
function showNote(n,animate=true){currentNote=n;$('#harvestEyebrow').textContent='A LITTLE WORD, JUST FOR YOU';$('#harvestCharacter').innerHTML=plantArt(n.mood,true);$('#harvestCharacter').classList.toggle('pulled',animate);$('#harvestTitle').textContent='이 말이 당신을 기다렸어요.';$('#harvestIntro').hidden=true;$('#harvestMessage').textContent=n.body;$('#harvestMessage').hidden=false;$('#harvestSubmit').hidden=true;$('#harvestActions').hidden=false;$('#harvestError').textContent='';$('#harvestFoot').textContent='이 말은 수확 바구니에서 다시 만날 수 있어요.';$('#thanks').textContent=n.thanked?'♥ 따뜻한 마음을 전했어요':'♡ 마음 잘 받았어요';$('#thanks').classList.toggle('sent',n.thanked);$('#thanks').disabled=n.thanked;$('#report').hidden=n.reported;if(!$('#harvestDialog').open)$('#harvestDialog').showModal()}
$('#harvestSubmit').onclick=async()=>{if(busy||!selected)return;busy=true;$('#harvestSubmit').disabled=true;$('#harvestError').textContent='';try{const next=await api('/harvest',{id:selected.id});farm=next;render();showNote(next.harvest)}catch(e){$('#harvestError').textContent=e.message;if(e.status===409){toast(e.message);$('#harvestDialog').close()}}finally{busy=false;$('#harvestSubmit').disabled=false;refresh()}};
$('#thanks').onclick=async()=>{if(!currentNote||busy)return;busy=true;try{farm=await api('/thanks',{id:currentNote.id});currentNote={...currentNote,thanked:true};showNote(currentNote,false);render();toast('심어준 농부에게 따뜻한 마음을 전했어요.')}catch(e){toast(e.message)}finally{busy=false}};
$('#report').onclick=async()=>{if(!currentNote||busy||!confirm('이 말을 신고하고 내 바구니에서 숨길까요?'))return;busy=true;try{farm=await api('/report',{id:currentNote.id});$('#harvestDialog').close();render();toast('이 말을 바구니에서 숨겼어요.')}catch(e){toast(e.message)}finally{busy=false}};
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#refresh').onclick=refresh;for(const id of ['guideButton','footerGuide'])$('#'+id).onclick=()=>$('#guideDialog').showModal();$('#guideClose').onclick=()=>$('#guideDialog').close();for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close()});window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(hash!=='field')navigate(hash)});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});navigate(location.hash.slice(1));refresh();setInterval(refresh,5000);
